	private static List<BindingSet> prepared(String query, BindingSet input, DefaultEvaluationStrategy strategy) {
		TupleExpr expression = strategy.optimizeForEmptyInput(parse(query), new EvaluationStatistics(), input);
		try (CloseableIteration<BindingSet> rows = strategy.precompile(expression)
				.evaluate(EmptyBindingSet.getInstance())) {
			return collect(rows);
		}
	}

	private static TupleExpr parse(String query) {
		return QueryParserUtil.parseQuery(QueryLanguage.SPARQL, query, null).getTupleExpr();
	}

	private static List<BindingSet> collect(CloseableIteration<BindingSet> rows) {
		List<BindingSet> result = new ArrayList<>();
		while (rows.hasNext()) {
			result.add(rows.next());
		}
		return result;
	}

	private record MemoryTripleSource(List<Statement> statements) implements TripleSource {
		@Override
		public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate, Value object,
				Resource... contexts) {
			return new CloseableIteratorIteration<>(statements.stream()
					.filter(statement -> subject == null || subject.equals(statement.getSubject()))
					.filter(statement -> predicate == null || predicate.equals(statement.getPredicate()))
					.filter(statement -> object == null || object.equals(statement.getObject()))
					.iterator());
		}

		@Override
		public ValueFactory getValueFactory() {
			return VF;
		}
	}
